describe('Modal Responsive on Mobile Screen Sizes', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should display modal in full width on mobile screen', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="modal"]').invoke('width').should('be.lessThan', 500);
  });

  it('should maintain modal content readability on small screens', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('be.visible');
    cy.get('[data-testid="modal-body"]').should('be.visible');
    cy.get('[data-testid="modal-footer"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').invoke('css', 'font-size').then((fontSize) => {
      expect(parseInt(fontSize)).to.be.greaterThan(12);
    });
  });

  it('should allow scrolling modal content on small screens when content exceeds viewport', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal-body"]').invoke('height').then((bodyHeight) => {
      cy.get('[data-testid="modal-body"]').invoke('prop', 'scrollHeight').then((scrollHeight) => {
        if (scrollHeight > bodyHeight) {
          cy.get('[data-testid="modal-body"]').scrollTo('bottom');
          cy.get('[data-testid="modal-body"]').invoke('prop', 'scrollTop').should('be.greaterThan', 0);
        }
      });
    });
  });

  it('should close modal on mobile when clicking close button', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');
  });

  it('should handle modal on tablet screen size responsively', () => {
    cy.viewport('ipad-2');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').invoke('width').then((width) => {
      expect(width).to.be.greaterThan(500);
      expect(width).to.be.lessThan(1024);
    });
  });

  it('should stack modal buttons vertically on mobile screens', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal-footer"] button').each(($button, index) => {
      if (index > 0) {
        cy.wrap($button).invoke('css', 'display').should('not.equal', 'inline');
      }
    });
  });

  it('should prevent modal overflow on mobile with long text content', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').invoke('css', 'overflow').should('match', /(auto|hidden|scroll)/);
    cy.get('[data-testid="modal"]').invoke('width').then((modalWidth) => {
      cy.get('[data-testid="modal-body"]').invoke('width').then((bodyWidth) => {
        expect(bodyWidth).to.be.lessThanOrEqual(modalWidth);
      });
    });
  });
});
